insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('menu-images','menu-images',true,3145728,array['image/webp'])
on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

create function private.menu_image_path_valid(p_path text) returns boolean language sql stable security definer set search_path='' as $$
  select p_path is null or exists(select 1 from private.menu_image_assets where path=p_path)
    or (p_path ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.webp$' and exists(select 1 from storage.objects where bucket_id='menu-images' and name=p_path));
$$;
revoke all on function private.menu_image_path_valid(text) from public,anon;
grant execute on function private.menu_image_path_valid(text) to authenticated;
alter table public.menu_items add column image_path text check(private.menu_image_path_valid(image_path));
create function private.guard_menu_image_actor() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if auth.uid() is not null and (TG_OP='INSERT' or new.image_path is distinct from old.image_path) and new.image_path is not null then
    if not exists(select 1 from private.menu_image_assets where path=new.image_path) and split_part(new.image_path,'/',1)<>auth.uid()::text then raise exception 'catalog_invalid_input'; end if;
  end if; return new;
end;
$$;
revoke all on function private.guard_menu_image_actor() from public,anon,authenticated;
create trigger guard_menu_image_actor before insert or update on public.menu_items for each row execute function private.guard_menu_image_actor();
create function public.set_menu_item_image(p_item_id text,p_expected_version integer,p_path text) returns integer language plpgsql security definer set search_path='' as $$
declare v integer;
begin
  perform private.require_catalog_owner();
  if p_expected_version is null or p_expected_version<1 or not private.menu_image_path_valid(p_path) then raise exception 'catalog_invalid_input'; end if;
  update public.menu_items set image_path=p_path where id=p_item_id and version=p_expected_version returning version into v;
  if v is null then
    if exists(select 1 from public.menu_items where id=p_item_id) then raise exception 'catalog_conflict'; else raise exception 'catalog_not_found'; end if;
  end if; return v;
end;
$$;
revoke all on function public.set_menu_item_image(text,integer,text) from public,anon,authenticated;
grant execute on function public.set_menu_item_image(text,integer,text) to authenticated;

create policy menu_image_owner_insert on storage.objects for insert to authenticated with check(
  bucket_id='menu-images' and name ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.webp$' and split_part(name,'/',1)=(select auth.uid())::text
  and exists(select 1 from public.admin_memberships where user_id=(select auth.uid()) and is_active and role='owner')
);
create policy menu_image_owner_read on storage.objects for select to authenticated using(
  bucket_id='menu-images' and split_part(name,'/',1)=(select auth.uid())::text
  and exists(select 1 from public.admin_memberships where user_id=(select auth.uid()) and is_active and role='owner')
);
create policy menu_image_owner_delete on storage.objects for delete to authenticated using(
  bucket_id='menu-images' and split_part(name,'/',1)=(select auth.uid())::text
  and exists(select 1 from public.admin_memberships where user_id=(select auth.uid()) and is_active and role='owner')
  and not exists(select 1 from public.menu_items where image_path=name)
);
-- No UPDATE policy: clients cannot overwrite an object.
alter function public.get_published_menu() rename to menu_without_images;
alter function public.menu_without_images() set schema private;
revoke all on function private.menu_without_images() from public,anon,authenticated;
create function public.get_published_menu() returns jsonb language sql stable security definer set search_path='' as $$
  with snapshot as materialized(select private.menu_without_images() as payload)
  select jsonb_set(payload,'{items}',coalesce((select jsonb_agg(i.value||jsonb_build_object('imagePath',m.image_path) order by i.ordinality)
    from jsonb_array_elements(payload->'items') with ordinality i(value,ordinality) join public.menu_items m on m.id=i.value->>'id'),'[]'::jsonb)) from snapshot;
$$;
revoke all on function public.get_published_menu() from public,anon,authenticated;
grant execute on function public.get_published_menu() to anon,authenticated;
